package main

import "fmt"

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	var r, x, y, tx, ty int64
	fmt.Scan(&r, &x, &y, &tx, &ty)

	dx, dy := tx-x, ty-y
	distSquared := dx*dx + dy*dy
	if distSquared == 0 {
		fmt.Println(0)
		return
	}

	step := 2 * r
	low := int64(0)
	high := (abs(dx) + abs(dy) + step - 1) / step

	for low < high {
		mid := (low + high) / 2
		reach := step * mid
		if reach*reach >= distSquared {
			high = mid
		} else {
			low = mid + 1
		}
	}

	fmt.Println(low)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var r, x, y, xp, yp int64
	fmt.Fscan(in, &r, &x, &y, &xp, &yp)

	dx, dy := xp-x, yp-y
	distSquared := dx*dx + dy*dy
	step := 2 * r

	var low, high int64
	high = 1
	for high*high*step*step < distSquared {
		high *= 2
	}

	for low < high {
		mid := (low + high) / 2
		if mid*mid*step*step >= distSquared {
			high = mid
		} else {
			low = mid + 1
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, low)
}

